#[derive(Serialize, Deserialize)]
struct StoredPayloadV1 {
    schema_version: u8,
    kind: StoredPayloadKind,
    input_requests: Option<InputRequests>,
    result: Option<JsonObject>,
    error: Option<JsonObject>,
}

#[derive(Serialize, Deserialize, Clone, Copy)]
#[serde(rename_all = "snake_case")]
enum StoredPayloadKind { Working, InputRequired, Completed, Failed, Cancelled }

fn reconstruct_payload(row_status: TaskStatus, p: StoredPayloadV1) -> Result<TaskPayload, StoreError> {
    if p.schema_version != 1 { return Err(StoreError::UnsupportedPayloadVersion); }
    let payload = match (p.kind, p.input_requests, p.result, p.error) {
        (StoredPayloadKind::Working, None, None, None) => TaskPayload::Working,
        (StoredPayloadKind::InputRequired, Some(input_requests), None, None) => TaskPayload::InputRequired { input_requests },
        (StoredPayloadKind::Completed, None, Some(result), None) => TaskPayload::Completed { result },
        (StoredPayloadKind::Failed, None, None, Some(error)) => TaskPayload::Failed { error },
        (StoredPayloadKind::Cancelled, None, None, None) => TaskPayload::Cancelled,
        _ => return Err(StoreError::PayloadShapeMismatch),
    };
    if row_status != payload.status() { return Err(StoreError::StatusPayloadMismatch); }
    Ok(payload)
}
